'use strict';
const A1_LESSONS = [
{id:'a1-01',title:'Nominativ – حالة الفاعل',type:'grammar',group:'الأساسيات',goal:'تحديد الفاعل واختيار الأداة الصحيحة في الجملة الاسمية والفعلية.',intro:'Nominativ هي الحالة التي نستخدمها غالباً للفاعل؛ أي الشخص أو الشيء الذي يقوم بالفعل أو نتحدث عنه في الجملة.',html:`<section class="lesson-section"><h3>1. ما معنى Nominativ؟</h3><p>في الجملة الألمانية نحتاج إلى معرفة <b>من يقوم بالفعل؟</b> أو <b>ما الشيء الذي نتحدث عنه؟</b>. هذا الجزء يسمى الفاعل، ويأتي في حالة Nominativ.</p><div class="callout"><strong>طريقة سهلة للتعرّف عليه:</strong> اسأل <b dir="ltr">Wer?</b> (مَن؟) مع الأشخاص، أو <b dir="ltr">Was?</b> (ماذا؟) مع الأشياء.</div></section><section class="lesson-section"><h3>2. أدوات التعريف في Nominativ</h3><p>يتغير شكل الأداة بحسب جنس الاسم. لذلك لا تحفظ الاسم منفرداً؛ احفظه دائماً مع أداته.</p><table class="grammar-table"><tr><th>الجنس</th><th>أداة التعريف</th><th>أداة التنكير</th><th>المثال</th></tr><tr><td>مذكر Maskulin</td><td>der</td><td>ein</td><td>der Mann</td></tr><tr><td>مؤنث Feminin</td><td>die</td><td>eine</td><td>die Frau</td></tr><tr><td>محايد Neutrum</td><td>das</td><td>ein</td><td>das Kind</td></tr><tr><td>جمع Plural</td><td>die</td><td>—</td><td>die Kinder</td></tr></table></section><section class="lesson-section"><h3>3. أمثلة مع التحليل</h3><div class="example-grid"><div class="example"><div class="de">Der Lehrer kommt.</div><div class="ar">المعلّم يأتي.</div><div class="why">Wer kommt? → Der Lehrer</div></div><div class="example"><div class="de">Eine Frau arbeitet.</div><div class="ar">امرأة تعمل.</div><div class="why">Wer arbeitet? → Eine Frau</div></div><div class="example"><div class="de">Das Kind spielt.</div><div class="ar">الطفل يلعب.</div><div class="why">Wer spielt? → Das Kind</div></div><div class="example"><div class="de">Die Bücher sind neu.</div><div class="ar">الكتب جديدة.</div><div class="why">Was ist neu? → Die Bücher</div></div></div></section><section class="lesson-section"><h3>4. ملاحظة مهمة</h3><p>بعد الفعل <b dir="ltr">sein</b> قد يأتي اسم أو صفة تصف الفاعل، وتبقى الأداة في هذه الجمل كما هي في Nominativ:</p><div class="example-grid"><div class="example"><div class="de">Das ist ein Arzt.</div><div class="ar">هذا طبيب.</div></div><div class="example"><div class="de">Die Frau ist Lehrerin.</div><div class="ar">المرأة معلّمة.</div></div></div><div class="mistake-box"><strong>خطأ شائع</strong><span>لا تختَر الأداة اعتماداً على الترجمة العربية وحدها. جنس الاسم في الألمانية قد يختلف عن جنس الكلمة في العربية.</span></div></section>`,ex:[{q:'___ Hund spielt im Garten.',o:['Der','Die','Das','Den'],a:'Der',why:'Hund اسم مذكر، وهو الفاعل؛ لذلك نستخدم der في Nominativ.'},{q:'أي كلمة تجيب عن سؤال Wer? في الجملة: Die Kinder lernen.',o:['Die Kinder','lernen','لا شيء'],a:'Die Kinder',why:'الأطفال هم من يقومون بفعل التعلّم، إذن هم الفاعل في Nominativ.'}]},
{id:'a1-02',title:'الضمائر الشخصية Personalpronomen',type:'grammar',group:'الأساسيات',goal:'استبدال الأسماء بضمائر الفاعل وفهم الفرق بين du وSie.',intro:'الضمير يحل محل الاسم حتى لا نكرر الاسم في كل جملة. احفظ الضمير مع معناه واستعماله.',html:`<section class="lesson-section"><h3>1. جدول الضمائر</h3><table class="grammar-table"><tr><th>الضمير</th><th>المعنى</th><th>متى نستخدمه؟</th></tr><tr><td>ich</td><td>أنا</td><td>المتكلم</td></tr><tr><td>du</td><td>أنتَ / أنتِ</td><td>مفرد غير رسمي</td></tr><tr><td>er</td><td>هو</td><td>مذكر</td></tr><tr><td>sie</td><td>هي</td><td>مؤنث</td></tr><tr><td>es</td><td>هو / هي لغير العاقل</td><td>اسم محايد</td></tr><tr><td>wir</td><td>نحن</td><td>المتكلمون</td></tr><tr><td>ihr</td><td>أنتم / أنتن</td><td>جمع غير رسمي</td></tr><tr><td>sie</td><td>هم / هن</td><td>جمع الغائب</td></tr><tr><td>Sie</td><td>حضرتك / حضراتكم</td><td>مخاطبة رسمية</td></tr></table></section><section class="lesson-section"><h3>2. كيف نختار الضمير؟</h3><p>انظر إلى الاسم: <b>der Mann</b> يصبح <b>er</b>، و<b>die Frau</b> تصبح <b>sie</b>، و<b>das Kind</b> يصبح <b>es</b>. أما الجمع فيصبح <b>sie</b>.</p><div class="example-grid"><div class="example"><div class="de">Maria ist Studentin. Sie lernt.</div><div class="ar">ماريا طالبة. هي تدرس.</div></div><div class="example"><div class="de">Das Auto ist neu. Es ist schnell.</div><div class="ar">السيارة جديدة. إنها سريعة.</div></div><div class="example"><div class="de">Paul und Tom sind Freunde. Sie spielen.</div><div class="ar">بول وتوم صديقان. هما يلعبان.</div></div><div class="example"><div class="de">Arbeiten Sie heute?</div><div class="ar">هل تعمل حضرتك اليوم؟</div></div></div></section><section class="lesson-section"><h3>3. du أم Sie؟</h3><p><b>du</b> مع الأصدقاء والعائلة والأشخاص الذين نتفق معهم على المخاطبة غير الرسمية. <b>Sie</b> في المواقف الرسمية ومع الأشخاص الذين لا نعرفهم غالباً. انتبه إلى أن Sie الرسمية تبدأ بحرف كبير دائماً.</p></section>`,ex:[{q:'Maria ist hier. ___ lernt Deutsch.',o:['Er','Sie','Es'],a:'Sie',why:'Maria اسم مؤنث، لذلك نستخدم sie.'},{q:'أي ضمير نستخدم في مخاطبة شخص باحترام؟',o:['du','ihr','Sie'],a:'Sie',why:'Sie بحرف كبير هي صيغة المخاطبة الرسمية.'}]},
{id:'a1-03',title:'الفعلان sein وhaben',type:'grammar',group:'الأساسيات',goal:'تصريف أهم فعلين في الألمانية واستخدامهما في جمل أساسية.',intro:'sein بمعنى يكون، وhaben بمعنى يملك أو لديه. يظهران كثيراً في التعريف والوصف والحديث عن الأشياء.',html:`<section class="lesson-section"><h3>1. تصريف sein</h3><table class="grammar-table"><tr><th>الضمير</th><th>التصريف</th><th>مثال</th></tr><tr><td>ich</td><td>bin</td><td>Ich bin müde.</td></tr><tr><td>du</td><td>bist</td><td>Du bist nett.</td></tr><tr><td>er / sie / es</td><td>ist</td><td>Er ist hier.</td></tr><tr><td>wir</td><td>sind</td><td>Wir sind bereit.</td></tr><tr><td>ihr</td><td>seid</td><td>Ihr seid pünktlich.</td></tr><tr><td>sie / Sie</td><td>sind</td><td>Sie sind freundlich.</td></tr></table><p>نستعمل sein للتعريف بالهوية أو المهنة أو الحالة أو المكان.</p></section><section class="lesson-section"><h3>2. تصريف haben</h3><table class="grammar-table"><tr><th>الضمير</th><th>التصريف</th><th>مثال</th></tr><tr><td>ich</td><td>habe</td><td>Ich habe Zeit.</td></tr><tr><td>du</td><td>hast</td><td>Du hast ein Buch.</td></tr><tr><td>er / sie / es</td><td>hat</td><td>Sie hat eine Tasche.</td></tr><tr><td>wir</td><td>haben</td><td>Wir haben Unterricht.</td></tr><tr><td>ihr</td><td>habt</td><td>Ihr habt Glück.</td></tr><tr><td>sie / Sie</td><td>haben</td><td>Sie haben Fragen.</td></tr></table></section><section class="lesson-section"><h3>3. قارن بينهما</h3><div class="example-grid"><div class="example"><div class="de">Ich bin Student.</div><div class="ar">أنا طالب.</div><div class="why">sein للتعريف أو الوصف.</div></div><div class="example"><div class="de">Ich habe einen Stift.</div><div class="ar">لديّ قلم.</div><div class="why">haben للملكية أو وجود شيء.</div></div></div><div class="mistake-box"><strong>انتبه</strong><span>لا نقول <b>ich bist</b> أو <b>du bin</b>. احفظ التصريف مع الضمير كأنهما كلمة واحدة.</span></div></section>`,ex:[{q:'Wir ___ heute zu Hause.',o:['ist','sind','seid'],a:'sind',why:'مع wir نستخدم sind.'},{q:'Du ___ einen Bruder.',o:['hat','hast','haben'],a:'hast',why:'مع du نستخدم hast.'}]},
{id:'a1-04',title:'تصريف الأفعال المنتظمة Präsens',type:'grammar',group:'الأفعال',goal:'تصريف الأفعال المنتظمة في المضارع وفهم نهاياتها.',intro:'الفعل المنتظم يتبع نمطاً ثابتاً غالباً: نحذف -en من المصدر ثم نضيف النهاية المناسبة للضمير.',html:`<section class="lesson-section"><h3>1. خطوات التصريف</h3><p>خذ الفعل <b>lernen</b> (يتعلّم). نحذف النهاية <b>-en</b> فنحصل على الجذر <b>lern-</b>، ثم نضيف نهايات التصريف.</p><table class="grammar-table"><tr><th>الضمير</th><th>النهاية</th><th>lernen</th><th>machen</th></tr><tr><td>ich</td><td>-e</td><td>lerne</td><td>mache</td></tr><tr><td>du</td><td>-st</td><td>lernst</td><td>machst</td></tr><tr><td>er/sie/es</td><td>-t</td><td>lernt</td><td>macht</td></tr><tr><td>wir</td><td>-en</td><td>lernen</td><td>machen</td></tr><tr><td>ihr</td><td>-t</td><td>lernt</td><td>macht</td></tr><tr><td>sie/Sie</td><td>-en</td><td>lernen</td><td>machen</td></tr></table></section><section class="lesson-section"><h3>2. استعمال الفعل داخل الجملة</h3><div class="example-grid"><div class="example"><div class="de">Ich lerne jeden Tag.</div><div class="ar">أدرس كل يوم.</div></div><div class="example"><div class="de">Du machst die Übung.</div><div class="ar">أنت تنجز التمرين.</div></div><div class="example"><div class="de">Wir wohnen in einer Wohnung.</div><div class="ar">نحن نسكن في شقة.</div></div><div class="example"><div class="de">Die Kinder spielen draußen.</div><div class="ar">الأطفال يلعبون في الخارج.</div></div></div><p>بعض الأفعال التي تنتهي جذورها بـ <b>-t</b> أو <b>-d</b> قد تحتاج إلى حرف e مساعد في بعض الصيغ، مثل <b>arbeiten → du arbeitest</b>.</p></section>`,ex:[{q:'Er ___ Deutsch.',o:['lernen','lernt','lerne'],a:'lernt',why:'مع er/sie/es نضيف -t إلى الجذر.'},{q:'Wir ___ zusammen.',o:['arbeiten','arbeitet','arbeitest'],a:'arbeiten',why:'مع wir نستخدم صيغة المصدر نفسها المنتهية بـ -en.'}]},
{id:'a1-05',title:'التعارف والتحية والتقديم',type:'skills',group:'التواصل',goal:'التحية، تقديم النفس، السؤال عن الاسم والبلد واللغة، واختيار الأسلوب الرسمي.',intro:'هذه العبارات هي أساس أول محادثة: ابدأ بالتحية، ثم الاسم، وبعدها سؤال بسيط للطرف الآخر.',html:`<section class="lesson-section"><h3>1. التحية والوداع</h3><table class="grammar-table"><tr><th>الألمانية</th><th>المعنى</th><th>الاستعمال</th></tr><tr><td>Guten Morgen</td><td>صباح الخير</td><td>في الصباح</td></tr><tr><td>Guten Tag</td><td>نهارك سعيد</td><td>تحية رسمية عامة</td></tr><tr><td>Guten Abend</td><td>مساء الخير</td><td>في المساء</td></tr><tr><td>Hallo</td><td>مرحباً</td><td>غير رسمية أو عامة</td></tr><tr><td>Auf Wiedersehen</td><td>إلى اللقاء</td><td>رسمية</td></tr><tr><td>Tschüss</td><td>وداعاً</td><td>غير رسمية</td></tr></table></section><section class="lesson-section"><h3>2. تقديم النفس</h3><div class="example-grid"><div class="example"><div class="de">Ich heiße Anna.</div><div class="ar">اسمي آنا.</div><button class="action-btn" data-say="Ich heiße Anna.">🔊 استمع</button></div><div class="example"><div class="de">Mein Name ist Paul.</div><div class="ar">اسمي بول.</div><button class="action-btn" data-say="Mein Name ist Paul.">🔊 استمع</button></div><div class="example"><div class="de">Woher kommst du?</div><div class="ar">من أين أنت؟ (غير رسمي)</div></div><div class="example"><div class="de">Woher kommen Sie?</div><div class="ar">من أين حضرتك؟ (رسمي)</div></div></div></section><section class="lesson-section"><h3>3. حوار قصير</h3><div class="callout"><b>Lisa:</b> Guten Tag! Ich heiße Lisa. Wie heißt du?<br><b>David:</b> Hallo Lisa! Ich heiße David. Freut mich.<br><b>Lisa:</b> Freut mich auch. Woher kommst du?<br><b>David:</b> Ich komme aus Spanien.</div><p><b>Freut mich</b> تعني: تشرفت بمعرفتك. ويمكن الرد: <b>Mich auch</b> أو <b>Freut mich auch</b>.</p></section>`,ex:[{q:'أي عبارة مناسبة لمخاطبة رسمية؟',o:['Wie heißt du?','Wie heißen Sie?','Woher kommst du?'],a:'Wie heißen Sie?',why:'Sie هي صيغة المخاطبة الرسمية، والفعل معها heißen.'},{q:'كيف نقول «تشرفت بمعرفتك»؟',o:['Freut mich.','Gute Nacht.','Bis morgen.'],a:'Freut mich.',why:'Freut mich عبارة شائعة عند التعارف.'}]},
{id:'a1-06',title:'ترتيب الجملة والأسئلة',type:'grammar',group:'بناء الجملة',goal:'بناء الجملة الخبرية وسؤال نعم/لا وأسئلة W مع المحافظة على مكان الفعل.',intro:'من أهم قواعد الألمانية أن الفعل المصرف يأتي في الموقع الثاني في الجملة الخبرية الأساسية.',html:`<section class="lesson-section"><h3>1. الجملة الخبرية: الفعل في الموقع الثاني</h3><p>الموقع الثاني يعني العنصر الثاني في ترتيب الجملة، وليس بالضرورة الكلمة الثانية إذا كان أول عنصر عبارة كاملة.</p><div class="example-grid"><div class="example"><div class="de">Ich lerne heute Deutsch.</div><div class="ar">أتعلم الألمانية اليوم.</div><div class="why">Ich (1) · lerne (2)</div></div><div class="example"><div class="de">Heute lerne ich Deutsch.</div><div class="ar">اليوم أتعلم الألمانية.</div><div class="why">Heute (1) · lerne (2)</div></div></div></section><section class="lesson-section"><h3>2. سؤال نعم أو لا</h3><p>في سؤال Ja/Nein نضع الفعل المصرف في بداية الجملة، ثم يأتي الفاعل.</p><div class="example-grid"><div class="example"><div class="de">Du lernst Deutsch.</div><div class="ar">أنت تتعلم الألمانية.</div></div><div class="example"><div class="de">Lernst du Deutsch?</div><div class="ar">هل تتعلم الألمانية؟</div></div></div></section><section class="lesson-section"><h3>3. أسئلة W</h3><table class="grammar-table"><tr><th>أداة السؤال</th><th>المعنى</th><th>مثال</th></tr><tr><td>Wer?</td><td>مَن؟</td><td>Wer ist das?</td></tr><tr><td>Was?</td><td>ماذا؟</td><td>Was machst du?</td></tr><tr><td>Wo?</td><td>أين؟</td><td>Wo wohnst du?</td></tr><tr><td>Woher?</td><td>من أين؟</td><td>Woher kommst du?</td></tr><tr><td>Wann?</td><td>متى؟</td><td>Wann beginnt der Kurs?</td></tr><tr><td>Wie?</td><td>كيف؟</td><td>Wie geht es dir?</td></tr><tr><td>Wie viel?</td><td>كم؟ للكمية</td><td>Wie viel kostet das?</td></tr></table></section>`,ex:[{q:'أي جملة صحيحة؟',o:['Heute ich lerne Deutsch.','Heute lerne ich Deutsch.','Heute Deutsch lerne ich.'],a:'Heute lerne ich Deutsch.',why:'عندما يبدأ الظرف الجملة، يأتي الفعل المصرف في الموقع الثاني ثم الفاعل.'},{q:'حوّل إلى سؤال: Du arbeitest heute.',o:['Arbeitest du heute?','Du arbeitest heute?','Heute du arbeitest?'],a:'Arbeitest du heute?',why:'في سؤال نعم/لا يتقدم الفعل إلى بداية الجملة.'}]},
{id:'a1-07',title:'جنس الأسماء والجمع',type:'grammar',group:'الأسماء والأدوات',goal:'معرفة جنس الاسم وتكوين الجمع وحفظ المفردات مع الأداة والجمع.',intro:'لكل اسم ألماني جنس نحوي، والجمع له أشكال مختلفة. لا توجد قاعدة واحدة تفسّر كل صيغ الجمع.',html:`<section class="lesson-section"><h3>1. الأجناس الثلاثة</h3><p>الأسماء الألمانية إما مذكر أو مؤنث أو محايد. يظهر الجنس في الأداة:</p><div class="example-grid"><div class="example"><div class="de">der Tisch</div><div class="ar">الطاولة – مذكر</div></div><div class="example"><div class="de">die Lampe</div><div class="ar">المصباح – مؤنث</div></div><div class="example"><div class="de">das Fenster</div><div class="ar">النافذة – محايد</div></div></div></section><section class="lesson-section"><h3>2. تكوين الجمع</h3><p>قد يتكوّن الجمع بإضافة -e أو -er أو -n/-en أو -s، وقد تتغير حركة الكلمة، وبعض الأسماء لا يتغير شكلها.</p><table class="grammar-table"><tr><th>المفرد</th><th>الجمع</th><th>ملاحظة</th></tr><tr><td>der Tag</td><td>die Tage</td><td>-e</td></tr><tr><td>das Kind</td><td>die Kinder</td><td>-er</td></tr><tr><td>die Frau</td><td>die Frauen</td><td>-en</td></tr><tr><td>das Auto</td><td>die Autos</td><td>-s</td></tr><tr><td>der Lehrer</td><td>die Lehrer</td><td>لا تغيير في الكلمة</td></tr></table></section><section class="lesson-section"><h3>3. طريقة الحفظ الصحيحة</h3><p>اكتب كل اسم في بطاقة بهذا الشكل: <b>der Tisch – die Tische</b>. بهذه الطريقة تتذكر الجنس والجمع معاً، وتقل أخطاء أدوات التعريف لاحقاً.</p></section>`,ex:[{q:'ما جمع das Kind؟',o:['die Kinde','die Kinder','die Kinds'],a:'die Kinder',why:'Kind يأخذ -er في الجمع.'},{q:'ما أداة كلمة Fenster؟',o:['der','die','das'],a:'das',why:'الكلمة هي das Fenster، احفظها مع أداتها.'}]},
{id:'a1-08',title:'أدوات التعريف والتنكير في Nominativ',type:'grammar',group:'الأسماء والأدوات',goal:'التمييز بين der/die/das وein/eine واختيار الأداة في الجملة.',intro:'الأداة المعرّفة تشير إلى شيء معروف أو محدد، أما أداة التنكير فتقدم شيئاً غير محدد أو جديداً.',html:`<section class="lesson-section"><h3>1. الأدوات الأساسية</h3><table class="grammar-table"><tr><th>الجنس</th><th>معرّف</th><th>نكرة</th><th>مثال</th></tr><tr><td>مذكر</td><td>der</td><td>ein</td><td>der Stuhl / ein Stuhl</td></tr><tr><td>مؤنث</td><td>die</td><td>eine</td><td>die Uhr / eine Uhr</td></tr><tr><td>محايد</td><td>das</td><td>ein</td><td>das Handy / ein Handy</td></tr><tr><td>جمع</td><td>die</td><td>لا توجد صيغة نكرة مماثلة</td><td>die Stühle</td></tr></table></section><section class="lesson-section"><h3>2. متى أستعمل كل واحدة؟</h3><p>إذا كنت تقدم شيئاً لأول مرة، قد تستعمل أداة التنكير. وعندما يصبح الشيء معروفاً في الحديث، تستعمل أداة التعريف.</p><div class="example-grid"><div class="example"><div class="de">Das ist ein Buch.</div><div class="ar">هذا كتاب.</div></div><div class="example"><div class="de">Das Buch ist interessant.</div><div class="ar">الكتاب ممتع.</div></div></div></section><section class="lesson-section"><h3>3. تذكير</h3><p>في الجمع نستعمل <b>die</b> مع الأسماء المعرفة، ولا توجد أداة تنكير جمع مباشرة مثل ein/eine.</p></section>`,ex:[{q:'Das ist ___ Lampe.',o:['ein','eine','einen'],a:'eine',why:'Lampe مؤنث، وفي Nominativ نستخدم eine.'},{q:'___ Auto ist schnell.',o:['Der','Die','Das'],a:'Das',why:'Auto محايد، وأداة التعريف في Nominativ هي das.'}]},
{id:'a1-09',title:'النفي nicht وkein',type:'grammar',group:'الأسماء والأدوات',goal:'نفي الأسماء والجمل والصفات والتمييز بين kein وnicht.',intro:'الألمانية تستخدم طريقتين أساسيتين للنفي. اختيار الأداة يعتمد على الجزء الذي تريد نفيه.',html:`<section class="lesson-section"><h3>1. استعمال kein</h3><p>نستخدم <b>kein</b> لنفي اسم يأتي غالباً مع أداة تنكير أو من دون أداة في سياق الإثبات. ويتغير حسب الجنس والحالة والعدد.</p><table class="grammar-table"><tr><th>الجنس</th><th>صيغة Nominativ</th><th>مثال</th></tr><tr><td>مذكر</td><td>kein</td><td>Das ist kein Stuhl.</td></tr><tr><td>مؤنث</td><td>keine</td><td>Das ist keine Tasche.</td></tr><tr><td>محايد</td><td>kein</td><td>Das ist kein Buch.</td></tr><tr><td>جمع</td><td>keine</td><td>Das sind keine Bücher.</td></tr></table></section><section class="lesson-section"><h3>2. استعمال nicht</h3><p>نستخدم <b>nicht</b> لنفي الفعل أو الصفة أو ظرف أو جملة كاملة، وكذلك مع الاسم الذي لديه أداة تعريف أو ملكية في كثير من التراكيب.</p><div class="example-grid"><div class="example"><div class="de">Ich arbeite heute nicht.</div><div class="ar">أنا لا أعمل اليوم.</div></div><div class="example"><div class="de">Das Buch ist nicht teuer.</div><div class="ar">الكتاب ليس غالياً.</div></div><div class="example"><div class="de">Das ist nicht mein Stift.</div><div class="ar">هذا ليس قلمي.</div></div><div class="example"><div class="de">Ich kenne den Mann nicht.</div><div class="ar">أنا لا أعرف الرجل.</div></div></div></section><div class="mistake-box"><strong>قاعدة تذكّر</strong><span>kein ينفي اسماً غير محدد غالباً، وnicht ينفي الفعل أو الصفة أو اسماً محدداً أو جزءاً آخر من الجملة.</span></div>`,ex:[{q:'Ich habe ___ Auto.',o:['nicht','kein','keine'],a:'kein',why:'Auto اسم محايد مع أداة تنكير، فننفيه بـ kein.'},{q:'Das Essen ist ___ warm.',o:['kein','nicht','keine'],a:'nicht',why:'هنا ننفي الصفة warm، لذلك نستخدم nicht.'}]},
{id:'a1-10',title:'Akkusativ – المفعول به المباشر',type:'grammar',group:'الحالات الإعرابية',goal:'تمييز المفعول به وفهم تغير أدوات المذكر في Akkusativ.',intro:'Akkusativ هي حالة المفعول به المباشر في كثير من الجمل. أهم علامة للمبتدئ هي تغير أداة المذكر.',html:`<section class="lesson-section"><h3>1. كيف أتعرف على المفعول به؟</h3><p>اسأل: من أو ماذا وقع عليه الفعل؟ في جملة <b>Ich sehe den Hund</b>، أنا أرى ماذا؟ الكلب. إذن den Hund هو المفعول به.</p></section><section class="lesson-section"><h3>2. جدول الأدوات</h3><table class="grammar-table"><tr><th>الجنس</th><th>Nominativ</th><th>Akkusativ</th></tr><tr><td>مذكر</td><td>der / ein</td><td><b>den / einen</b></td></tr><tr><td>مؤنث</td><td>die / eine</td><td>die / eine</td></tr><tr><td>محايد</td><td>das / ein</td><td>das / ein</td></tr><tr><td>جمع</td><td>die</td><td>die</td></tr></table><p>لاحظ أن التغيير الواضح في هذا الجدول يقع في المذكر فقط.</p></section><section class="lesson-section"><h3>3. أمثلة مقارنة</h3><div class="example-grid"><div class="example"><div class="de">Der Mann kauft einen Computer.</div><div class="ar">الرجل يشتري حاسوباً.</div><div class="why">Der Mann فاعل · einen Computer مفعول به.</div></div><div class="example"><div class="de">Die Frau liest ein Buch.</div><div class="ar">المرأة تقرأ كتاباً.</div><div class="why">ein Buch محايد، فلا يتغير شكله.</div></div><div class="example"><div class="de">Wir trinken den Kaffee.</div><div class="ar">نحن نشرب القهوة.</div><div class="why">der Kaffee أصبح den Kaffee.</div></div></div></section>`,ex:[{q:'Ich sehe ___ Mann.',o:['der','den','dem'],a:'den',why:'Mann مذكر ومفعول به مباشر؛ der يتحول إلى den.'},{q:'Sie kauft ___ Tasche.',o:['eine','einen','einer'],a:'eine',why:'Tasche مؤنث، وتبقى أداة التنكير eine في Akkusativ.'}]},
{id:'a1-11',title:'أدوات الملكية Possessivartikel',type:'grammar',group:'الأسماء والأدوات',goal:'التعبير عن الملكية باستعمال mein وdein وsein وihr وغيرها.',intro:'أداة الملكية تخبرنا لمن يعود الشيء. شكلها يتأثر بجنس الاسم الذي يأتي بعدها.',html:`<section class="lesson-section"><h3>1. أدوات الملكية الأساسية</h3><table class="grammar-table"><tr><th>المالك</th><th>الأداة</th><th>مثال</th></tr><tr><td>ich</td><td>mein</td><td>mein Buch</td></tr><tr><td>du</td><td>dein</td><td>dein Stift</td></tr><tr><td>er</td><td>sein</td><td>sein Bruder</td></tr><tr><td>sie (هي)</td><td>ihr</td><td>ihr Haus</td></tr><tr><td>es</td><td>sein</td><td>sein Futter</td></tr><tr><td>wir</td><td>unser</td><td>unser Lehrer</td></tr><tr><td>ihr</td><td>euer</td><td>euer Kurs</td></tr><tr><td>sie (هم) / Sie</td><td>ihr / Ihr</td><td>ihr Kind / Ihr Name</td></tr></table></section><section class="lesson-section"><h3>2. النهايات مع الاسم</h3><p>في Nominativ تتبع النهاية جنس الاسم:</p><table class="grammar-table"><tr><th>الاسم</th><th>مع mein</th><th>المعنى</th></tr><tr><td>der Vater</td><td>mein Vater</td><td>أبي</td></tr><tr><td>die Mutter</td><td>meine Mutter</td><td>أمي</td></tr><tr><td>das Kind</td><td>mein Kind</td><td>طفلي</td></tr><tr><td>die Freunde</td><td>meine Freunde</td><td>أصدقائي</td></tr></table></section><section class="lesson-section"><h3>3. أمثلة</h3><div class="example-grid"><div class="example"><div class="de">Das ist meine Schwester.</div><div class="ar">هذه أختي.</div></div><div class="example"><div class="de">Unser Haus ist groß.</div><div class="ar">منزلنا كبير.</div></div></div><p>انتبه: <b>sein</b> تعني «ملكه» عندما تكون أداة ملكية، لكنها أيضاً مصدر الفعل «يكون». السياق هو الذي يحدد المعنى.</p></section>`,ex:[{q:'Das ist ___ Mutter. (ich)',o:['mein','meine','meinen'],a:'meine',why:'Mutter مؤنث، لذلك نضيف -e: meine.'},{q:'Peter sucht ___ Schlüssel. (er)',o:['sein','seine','seinen'],a:'seinen',why:'Schlüssel مذكر ومفعول به Akkusativ، لذلك sein يصبح seinen.'}]},
{id:'a1-12',title:'ضمائر المفعول به Akkusativpronomen',type:'grammar',group:'الحالات الإعرابية',goal:'استبدال المفعول به بضمائر mich وdich وihn وغيرها.',intro:'بدلاً من تكرار الاسم بعد الفعل، نستعمل ضمير المفعول به المناسب.',html:`<section class="lesson-section"><h3>1. جدول الضمائر</h3><table class="grammar-table"><tr><th>Nominativ</th><th>Akkusativ</th><th>المعنى</th></tr><tr><td>ich</td><td>mich</td><td>أنا ← إياي</td></tr><tr><td>du</td><td>dich</td><td>أنت ← إياك</td></tr><tr><td>er</td><td>ihn</td><td>هو ← إياه</td></tr><tr><td>sie</td><td>sie</td><td>هي ← إياها</td></tr><tr><td>es</td><td>es</td><td>هو/هي لغير العاقل</td></tr><tr><td>wir</td><td>uns</td><td>نحن ← إيانا</td></tr><tr><td>ihr</td><td>euch</td><td>أنتم ← إياكم</td></tr><tr><td>sie / Sie</td><td>sie / Sie</td><td>هم / حضرتك</td></tr></table></section><section class="lesson-section"><h3>2. كيف نستخدمها؟</h3><div class="example-grid"><div class="example"><div class="de">Er sieht mich.</div><div class="ar">هو يراني.</div></div><div class="example"><div class="de">Ich kenne ihn.</div><div class="ar">أنا أعرفه.</div></div><div class="example"><div class="de">Wir besuchen sie.</div><div class="ar">نحن نزورها / نزورهم.</div></div><div class="example"><div class="de">Kannst du uns hören?</div><div class="ar">هل تستطيع سماعنا؟</div></div></div><p>يحدد السياق معنى sie: قد تعني «إياها» أو «إياهم» أو صيغة الاحترام Sie.</p></section>`,ex:[{q:'Ich sehe Paul. Ich sehe ___.',o:['er','ihn','ihm'],a:'ihn',why:'Paul مذكر ومفعول به مباشر، لذلك نستخدم ihn.'},{q:'Sie besucht Anna und mich. Sie besucht ___.',o:['wir','uns','euch'],a:'uns',why:'ضمير wir في Akkusativ يصبح uns.'}]},
{id:'a1-13',title:'الصفات والوصف Adjektive',type:'grammar',group:'الوصف',goal:'وصف الأشخاص والأشياء باستعمال الصفات بعد sein وفي جمل بسيطة.',intro:'الصفة تصف شخصاً أو شيئاً: كبير، صغير، جميل، سريع، غالٍ. في هذا الدرس نركز على استعمالها بعد sein.',html:`<section class="lesson-section"><h3>1. الصفة بعد sein</h3><p>عندما تأتي الصفة بعد فعل sein، لا نضيف إليها نهاية في هذا التركيب الأساسي.</p><div class="example-grid"><div class="example"><div class="de">Das Haus ist groß.</div><div class="ar">المنزل كبير.</div></div><div class="example"><div class="de">Die Tasche ist teuer.</div><div class="ar">الحقيبة غالية.</div></div><div class="example"><div class="de">Der Film ist interessant.</div><div class="ar">الفيلم ممتع.</div></div><div class="example"><div class="de">Die Kinder sind müde.</div><div class="ar">الأطفال متعبون.</div></div></div></section><section class="lesson-section"><h3>2. صفات شائعة</h3><table class="grammar-table"><tr><th>Deutsch</th><th>العربية</th><th>Deutsch</th><th>العربية</th></tr><tr><td>groß</td><td>كبير</td><td>klein</td><td>صغير</td></tr><tr><td>schön</td><td>جميل</td><td>hässlich</td><td>قبيح</td></tr><tr><td>teuer</td><td>غالٍ</td><td>billig</td><td>رخيص</td></tr><tr><td>schnell</td><td>سريع</td><td>langsam</td><td>بطيء</td></tr><tr><td>neu</td><td>جديد</td><td>alt</td><td>قديم / كبير في السن</td></tr><tr><td>müde</td><td>متعب</td><td>freundlich</td><td>ودود</td></tr></table></section><section class="lesson-section"><h3>3. السؤال عن الوصف</h3><p>نسأل غالباً <b dir="ltr">Wie ist ...?</b> أي: كيف هو؟ أو ما صفته؟</p><div class="example"><div class="de">Wie ist das Wetter? – Es ist sonnig.</div><div class="ar">كيف الطقس؟ – إنه مشمس.</div></div></section>`,ex:[{q:'Das Auto ist ___. (سريع)',o:['schnell','Schnell','schnelle'],a:'schnell',why:'بعد ist تأتي الصفة دون نهاية في هذا التركيب.'},{q:'ما عكس teuer؟',o:['klein','billig','langsam'],a:'billig',why:'teuer تعني غالٍ، وعكسها billig أي رخيص.'}]},
{id:'a1-14',title:'الأفعال الناقصة Modalverben',type:'grammar',group:'الأفعال',goal:'التعبير عن القدرة والضرورة والرغبة والسماح باستعمال الأفعال الناقصة.',intro:'الفعل الناقص يتصرف بحسب الضمير، بينما يأتي الفعل الأساسي في نهاية الجملة بصيغة المصدر.',html:`<section class="lesson-section"><h3>1. أهم المعاني</h3><table class="grammar-table"><tr><th>الفعل</th><th>المعنى</th><th>مثال</th></tr><tr><td>können</td><td>يستطيع / يمكن</td><td>Ich kann schwimmen.</td></tr><tr><td>müssen</td><td>يجب / مضطر</td><td>Ich muss lernen.</td></tr><tr><td>wollen</td><td>يريد</td><td>Wir wollen reisen.</td></tr><tr><td>dürfen</td><td>مسموح له</td><td>Du darfst gehen.</td></tr><tr><td>möchten</td><td>يودّ / يرغب بأدب</td><td>Ich möchte Tee.</td></tr></table></section><section class="lesson-section"><h3>2. ترتيب الجملة</h3><p>الفعل الناقص المصرف يأتي في الموقع الثاني، والفعل الأساسي يذهب إلى نهاية الجملة بصيغة المصدر.</p><div class="example-grid"><div class="example"><div class="de">Sie kann gut kochen.</div><div class="ar">هي تستطيع الطبخ جيداً.</div><div class="why">kann في الموقع الثاني · kochen في النهاية.</div></div><div class="example"><div class="de">Wir müssen heute arbeiten.</div><div class="ar">يجب علينا العمل اليوم.</div></div></div></section><section class="lesson-section"><h3>3. تصريف können وmüssen</h3><table class="grammar-table"><tr><th>الضمير</th><th>können</th><th>müssen</th></tr><tr><td>ich</td><td>kann</td><td>muss</td></tr><tr><td>du</td><td>kannst</td><td>musst</td></tr><tr><td>er/sie/es</td><td>kann</td><td>muss</td></tr><tr><td>wir</td><td>können</td><td>müssen</td></tr><tr><td>ihr</td><td>könnt</td><td>müsst</td></tr><tr><td>sie/Sie</td><td>können</td><td>müssen</td></tr></table></section>`,ex:[{q:'Ich ___ Deutsch sprechen. (أستطيع)',o:['kann','können','kannst'],a:'kann',why:'مع ich نستخدم kann، والفعل sprechen يبقى في المصدر في نهاية الجملة.'},{q:'Wir müssen heute ___.',o:['arbeitet','arbeiten','arbeitest'],a:'arbeiten',why:'بعد الفعل الناقص يأتي الفعل الأساسي بصيغة المصدر.'}]},
{id:'a1-15',title:'تغير حرف العلة في المضارع',type:'grammar',group:'الأفعال',goal:'التعرف على بعض الأفعال التي يتغير جذرها مع du وer/sie/es.',intro:'بعض الأفعال لا تتبع النمط المنتظم تماماً؛ قد يتغير حرف العلة في الجذر عند du وer/sie/es.',html:`<section class="lesson-section"><h3>1. أمثلة على التغيير</h3><table class="grammar-table"><tr><th>المصدر</th><th>du</th><th>er/sie/es</th><th>المعنى</th></tr><tr><td>fahren</td><td>fährst</td><td>fährt</td><td>يسافر / يقود</td></tr><tr><td>lesen</td><td>liest</td><td>liest</td><td>يقرأ</td></tr><tr><td>sehen</td><td>siehst</td><td>sieht</td><td>يرى</td></tr><tr><td>sprechen</td><td>sprichst</td><td>spricht</td><td>يتحدث</td></tr><tr><td>essen</td><td>isst</td><td>isst</td><td>يأكل</td></tr></table></section><section class="lesson-section"><h3>2. هل يتغير مع كل الضمائر؟</h3><p>في هذه المجموعة يتركز تغيير حرف العلة عادة في du وer/sie/es. أما ich وwir وihr وsie/Sie فتحتفظ غالباً بشكل الجذر الأصلي.</p><div class="example-grid"><div class="example"><div class="de">Ich lese ein Buch.</div><div class="ar">أنا أقرأ كتاباً.</div></div><div class="example"><div class="de">Du liest ein Buch.</div><div class="ar">أنت تقرأ كتاباً.</div></div><div class="example"><div class="de">Er fährt nach Berlin.</div><div class="ar">هو يسافر إلى برلين.</div></div></div></section><div class="mistake-box"><strong>طريقة الحفظ</strong><span>احفظ الفعل مع شكل du وer/sie/es، ولا تحاول تطبيق تغيير حرف العلة على كل الأفعال.</span></div>`,ex:[{q:'Er ___ gern Bücher. (lesen)',o:['lest','liest','lese'],a:'liest',why:'lesen يتغير إلى ie مع er/sie/es: er liest.'},{q:'Du ___ sehr gut Deutsch. (sprechen)',o:['sprichst','sprechst','spricht'],a:'sprichst',why:'sprechen يتغير e إلى i مع du: du sprichst.'}]},
{id:'a1-16',title:'الأفعال المنفصلة Trennbare Verben',type:'grammar',group:'الأفعال',goal:'فهم الأفعال ذات البادئة المنفصلة ومكان البادئة في الجملة.',intro:'بعض الأفعال تتكون من بادئة وفعل. في الجملة الرئيسية ينفصل الجزء الأول ويذهب إلى نهاية الجملة.',html:`<section class="lesson-section"><h3>1. ما الفعل المنفصل؟</h3><p>مثل <b>aufstehen</b> (ينهض)، وهو مكوّن من auf + stehen. عند تصريفه في جملة رئيسية، نضع الفعل المصرف في الموقع الثاني والبادئة في نهاية الجملة.</p><div class="example-grid"><div class="example"><div class="de">Ich stehe um sieben Uhr auf.</div><div class="ar">أنهض في الساعة السابعة.</div></div><div class="example"><div class="de">Der Zug fährt um acht Uhr ab.</div><div class="ar">ينطلق القطار في الثامنة.</div></div><div class="example"><div class="de">Sie kauft heute ein.</div><div class="ar">هي تتسوق اليوم.</div></div></div></section><section class="lesson-section"><h3>2. أفعال شائعة</h3><table class="grammar-table"><tr><th>الفعل</th><th>المعنى</th><th>مثال مختصر</th></tr><tr><td>aufstehen</td><td>ينهض</td><td>Ich stehe auf.</td></tr><tr><td>einkaufen</td><td>يتسوق</td><td>Wir kaufen ein.</td></tr><tr><td>anrufen</td><td>يتصل هاتفياً</td><td>Er ruft an.</td></tr><tr><td>fernsehen</td><td>يشاهد التلفاز</td><td>Sie sieht fern.</td></tr><tr><td>mitkommen</td><td>يأتي مع</td><td>Kommst du mit?</td></tr></table></section><section class="lesson-section"><h3>3. مع الفعل الناقص</h3><p>بعد Modalverb يبقى الفعل المنفصل في المصدر في نهاية الجملة، ولا تنفصل البادئة.</p><div class="example"><div class="de">Ich muss morgen früh aufstehen.</div><div class="ar">يجب أن أنهض باكراً غداً.</div></div></section>`,ex:[{q:'Ich ___ um sechs Uhr ___. (aufstehen)',o:['stehe / auf','aufstehe / —','steht / auf'],a:'stehe / auf',why:'الفعل المصرف stehe في الموقع الثاني، والبادئة auf في النهاية.'},{q:'Wir müssen heute ___. (einkaufen)',o:['kaufen ein','einkaufen','einkauft'],a:'einkaufen',why:'بعد müssen يأتي الفعل في المصدر، لذلك تبقى einkaufen كلمة واحدة.'}]},
{id:'a1-17',title:'Perfekt – الماضي مع الأفعال المنتظمة',type:'grammar',group:'الأزمنة',goal:'تكوين الماضي المحكي للأفعال المنتظمة باستخدام haben وPartizip II.',intro:'Perfekt هو الزمن الشائع في المحادثة للحديث عن أحداث انتهت في الماضي.',html:`<section class="lesson-section"><h3>1. تركيب Perfekt</h3><p>يتكون غالباً من فعل مساعد مصرف في الموقع الثاني، ثم Partizip II في نهاية الجملة.</p><div class="callout"><strong>التركيب:</strong> الفاعل + haben/sein المصرف + بقية الجملة + Partizip II.</div><div class="example"><div class="de">Ich habe Deutsch gelernt.</div><div class="ar">لقد تعلمت الألمانية.</div><div class="why">habe فعل مساعد · gelernt التصريف الثالث.</div></div></section><section class="lesson-section"><h3>2. تكوين Partizip II المنتظم</h3><p>في كثير من الأفعال المنتظمة نضيف <b>ge-</b> في البداية و<b>-t</b> في النهاية إلى الجذر.</p><table class="grammar-table"><tr><th>المصدر</th><th>Partizip II</th><th>المعنى</th></tr><tr><td>lernen</td><td>gelernt</td><td>تعلّم</td></tr><tr><td>machen</td><td>gemacht</td><td>فعل / صنع</td></tr><tr><td>spielen</td><td>gespielt</td><td>لعب</td></tr><tr><td>kaufen</td><td>gekauft</td><td>اشترى</td></tr><tr><td>fragen</td><td>gefragt</td><td>سأل</td></tr></table></section><section class="lesson-section"><h3>3. أمثلة في سياق</h3><div class="example-grid"><div class="example"><div class="de">Wir haben Fußball gespielt.</div><div class="ar">لعبنا كرة القدم.</div></div><div class="example"><div class="de">Sie hat Brot gekauft.</div><div class="ar">اشترت خبزاً.</div></div><div class="example"><div class="de">Er hat viel gelernt.</div><div class="ar">درس كثيراً.</div></div></div></section>`,ex:[{q:'Ich habe ein Buch ___. (kaufen)',o:['gekauft','gekaufen','kaufte'],a:'gekauft',why:'Partizip II للفعل المنتظم kaufen هو gekauft.'},{q:'Wir haben Musik ___. (hören)',o:['gehört','gehören','gehoren'],a:'gehört',why:'الفعل hören يصبح gehört.'}]},
{id:'a1-18',title:'Perfekt – الأفعال غير المنتظمة واختيار haben/sein',type:'grammar',group:'الأزمنة',goal:'التعرف على Partizip II غير المنتظم ومعرفة متى نستخدم sein أو haben.',intro:'ليست كل الأفعال تتبع قاعدة ge-...-t. بعض الأفعال تتغير حروفها، كما أن بعض أفعال الحركة تستعمل sein.',html:`<section class="lesson-section"><h3>1. أفعال غير منتظمة شائعة</h3><table class="grammar-table"><tr><th>المصدر</th><th>Partizip II</th><th>المعنى</th></tr><tr><td>gehen</td><td>gegangen</td><td>ذهب</td></tr><tr><td>kommen</td><td>gekommen</td><td>أتى</td></tr><tr><td>fahren</td><td>gefahren</td><td>سافر / قاد</td></tr><tr><td>sehen</td><td>gesehen</td><td>رأى</td></tr><tr><td>essen</td><td>gegessen</td><td>أكل</td></tr><tr><td>trinken</td><td>getrunken</td><td>شرب</td></tr><tr><td>schreiben</td><td>geschrieben</td><td>كتب</td></tr></table></section><section class="lesson-section"><h3>2. متى نستخدم sein؟</h3><p>نستخدم sein مع كثير من أفعال الانتقال من مكان إلى آخر أو التغير في الحالة، مثل gehen وkommen وfahren. أما أفعال كثيرة أخرى فتستعمل haben.</p><div class="example-grid"><div class="example"><div class="de">Ich bin nach Hause gegangen.</div><div class="ar">ذهبت إلى المنزل.</div><div class="why">gehen → bin gegangen</div></div><div class="example"><div class="de">Sie ist spät gekommen.</div><div class="ar">وصلت متأخرة.</div><div class="why">kommen → ist gekommen</div></div><div class="example"><div class="de">Wir haben Pizza gegessen.</div><div class="ar">أكلنا بيتزا.</div><div class="why">essen → haben gegessen</div></div></div></section><section class="lesson-section"><h3>3. أفعال ذات بادئة في Perfekt</h3><p>الأفعال المنفصلة غالباً تأتي فيها <b>ge</b> بين البادئة والفعل: <b>aufstehen → aufgestanden</b>. أما الأفعال ذات البادئة غير المنفصلة مثل be-, ver-, er- فلا تأخذ ge في البداية عادةً: <b>besuchen → besucht</b>.</p></section>`,ex:[{q:'Wir ___ nach Hause gegangen.',o:['haben','sind','seid'],a:'sind',why:'gehen فعل انتقال ويستعمل sein في Perfekt.'},{q:'Er hat seine Freundin ___. (besuchen)',o:['gebesucht','besucht','besuchen'],a:'besucht',why:'besuchen يبدأ ببادئة غير منفصلة be-، لذلك لا نضيف ge.'}]},
{id:'a1-19',title:'الوقت والأيام والتاريخ والأرقام',type:'skills',group:'التواصل',goal:'السؤال عن الوقت والتاريخ وفهم الأرقام والمواعيد.',intro:'تحتاج إلى الأرقام والوقت في المواعيد، المواصلات، التسوق والدراسة. تدرب على سماع الرقم ونطقه.',html:`<section class="lesson-section"><h3>1. أيام الأسبوع</h3><table class="grammar-table"><tr><th>Deutsch</th><th>العربية</th><th>Deutsch</th><th>العربية</th></tr><tr><td>Montag</td><td>الاثنين</td><td>Freitag</td><td>الجمعة</td></tr><tr><td>Dienstag</td><td>الثلاثاء</td><td>Samstag</td><td>السبت</td></tr><tr><td>Mittwoch</td><td>الأربعاء</td><td>Sonntag</td><td>الأحد</td></tr><tr><td>Donnerstag</td><td>الخميس</td><td>—</td><td>—</td></tr></table></section><section class="lesson-section"><h3>2. السؤال عن الوقت</h3><div class="example-grid"><div class="example"><div class="de">Wie spät ist es?</div><div class="ar">كم الساعة؟</div></div><div class="example"><div class="de">Wie viel Uhr ist es?</div><div class="ar">كم الساعة؟</div></div><div class="example"><div class="de">Es ist acht Uhr.</div><div class="ar">الساعة الثامنة.</div></div><div class="example"><div class="de">Der Kurs beginnt um neun Uhr.</div><div class="ar">تبدأ الدورة في الساعة التاسعة.</div></div></div></section><section class="lesson-section"><h3>3. الأشهر والتاريخ</h3><p>أسماء الأشهر: Januar, Februar, März, April, Mai, Juni, Juli, August, September, Oktober, November, Dezember.</p><p>للسؤال عن التاريخ نقول <b dir="ltr">Der Wievielte ist heute?</b> وللإجابة: <b dir="ltr">Heute ist der vierte Mai.</b></p><div class="callout">حرف الجر <b>am</b> يستخدم كثيراً مع أيام الأسبوع والتواريخ: <b>am Montag</b>، أما <b>um</b> فيستخدم مع الساعة: <b>um acht Uhr</b>.</div></section>`,ex:[{q:'نقول: يبدأ الدرس ___ acht Uhr.',o:['am','um','im'],a:'um',why:'um تستخدم مع الساعة المحددة.'},{q:'ما معنى Dienstag؟',o:['الثلاثاء','الخميس','الأحد'],a:'الثلاثاء',why:'Dienstag هو يوم الثلاثاء.'}]},
{id:'a1-20',title:'المكان وحالة Dativ',type:'grammar',group:'حروف الجر',goal:'وصف مكان وجود شيء واستعمال حروف الجر الأساسية مع Dativ.',intro:'عند السؤال Wo? (أين؟) نحتاج غالباً إلى تعبير مكاني، وبعض حروف الجر تأخذ Dativ.',html:`<section class="lesson-section"><h3>1. السؤال عن المكان</h3><p>السؤال <b dir="ltr">Wo?</b> يعني أين؟ ونستعمله عندما نصف مكان وجود شخص أو شيء، لا اتجاه الحركة.</p><div class="example-grid"><div class="example"><div class="de">Das Buch liegt auf dem Tisch.</div><div class="ar">الكتاب موضوع على الطاولة.</div></div><div class="example"><div class="de">Die Lampe steht neben dem Bett.</div><div class="ar">المصباح بجانب السرير.</div></div></div></section><section class="lesson-section"><h3>2. أدوات Dativ الأساسية</h3><table class="grammar-table"><tr><th>الجنس</th><th>Nominativ</th><th>Dativ</th></tr><tr><td>مذكر</td><td>der</td><td>dem</td></tr><tr><td>مؤنث</td><td>die</td><td>der</td></tr><tr><td>محايد</td><td>das</td><td>dem</td></tr><tr><td>جمع</td><td>die</td><td>den + n غالباً</td></tr></table></section><section class="lesson-section"><h3>3. حروف جر شائعة للمكان</h3><p>من الحروف التي تأتي مع Dativ عند وصف الموقع: <b>bei</b>، <b>mit</b>، <b>von</b>، <b>zu</b>، وكذلك حروف المكان المتغيرة عندما تجيب عن Wo? مثل in وauf وan.</p><div class="example-grid"><div class="example"><div class="de">Ich bin beim Arzt.</div><div class="ar">أنا عند الطبيب.</div></div><div class="example"><div class="de">Die Kinder sind im Garten.</div><div class="ar">الأطفال في الحديقة.</div></div></div></section>`,ex:[{q:'Das Handy liegt auf ___ Tisch.',o:['der','dem','den'],a:'dem',why:'Tisch مذكر، وWo? يدل على المكان؛ لذلك Dativ: dem Tisch.'},{q:'Ich bin ___ Schule.',o:['in der','in die','in den'],a:'in der',why:'Schule مؤنث، ووصف المكان مع Wo? يأخذ Dativ: in der Schule.'}]},
{id:'a1-21',title:'الاتجاه والحركة Dativ / Akkusativ',type:'grammar',group:'حروف الجر',goal:'التمييز بين Wo? للمكان وWohin? للاتجاه مع حروف الجر المتغيرة.',intro:'بعض حروف الجر مثل in وauf وan تتغير حالتها بحسب المعنى: هل نصف مكاناً ثابتاً أم حركة باتجاه مكان؟',html:`<section class="lesson-section"><h3>1. الفرق بين Wo? وWohin?</h3><table class="grammar-table"><tr><th>السؤال</th><th>المعنى</th><th>الحالة</th><th>مثال</th></tr><tr><td>Wo?</td><td>أين؟ موقع ثابت</td><td>Dativ</td><td>Ich bin in der Schule.</td></tr><tr><td>Wohin?</td><td>إلى أين؟ اتجاه</td><td>Akkusativ</td><td>Ich gehe in die Schule.</td></tr></table></section><section class="lesson-section"><h3>2. حروف الجر المتغيرة</h3><p>من أشهرها: an, auf, hinter, in, neben, über, unter, vor, zwischen. مع المكان الثابت تأخذ Dativ، ومع الاتجاه أو الانتقال إلى مكان تأخذ Akkusativ.</p><div class="example-grid"><div class="example"><div class="de">Das Bild hängt an der Wand.</div><div class="ar">الصورة معلقة على الحائط. (مكان)</div></div><div class="example"><div class="de">Ich hänge das Bild an die Wand.</div><div class="ar">أعلّق الصورة على الحائط. (اتجاه)</div></div><div class="example"><div class="de">Die Katze ist unter dem Tisch.</div><div class="ar">القطة تحت الطاولة.</div></div><div class="example"><div class="de">Die Katze läuft unter den Tisch.</div><div class="ar">القطة تجري إلى تحت الطاولة.</div></div></div></section><div class="mistake-box"><strong>لا تعتمد على وجود حركة جسدية فقط</strong><span>اسأل عن المعنى: هل الجملة تجيب عن أين يوجد الشيء؟ أم إلى أين يتحرك؟ هذا هو المفتاح الأساسي.</span></div>`,ex:[{q:'Wohin gehst du? – Ich gehe in ___ Park.',o:['dem','den','der'],a:'den',why:'Wohin? اتجاه إلى الحديقة، وPark مذكر في Akkusativ: in den Park.'},{q:'Wo ist das Kind? – Es ist in ___ Zimmer.',o:['das','dem','den'],a:'dem',why:'Wo? موقع ثابت، Zimmer محايد في Dativ: in dem Zimmer / im Zimmer.'}]},
{id:'a1-22',title:'الأمر والاقتراحات Imperativ',type:'grammar',group:'التواصل',goal:'إعطاء تعليمات وطلبات واقتراح نشاط بطريقة مباشرة أو مهذبة.',intro:'نستعمل صيغة الأمر لإعطاء تعليمات أو طلب فعل، ونستعمل صيغ الاقتراح للتخطيط مع الآخرين.',html:`<section class="lesson-section"><h3>1. الأمر مع du</h3><p>في صيغة الأمر غير الرسمية نحذف الضمير غالباً ونستخدم صيغة الفعل المناسبة. مثال: <b>kommen → Komm!</b> و<b>machen → Mach!</b>.</p><div class="example-grid"><div class="example"><div class="de">Komm bitte!</div><div class="ar">تعال من فضلك!</div></div><div class="example"><div class="de">Lies den Text!</div><div class="ar">اقرأ النص!</div></div></div></section><section class="lesson-section"><h3>2. الأمر الرسمي Sie</h3><p>في الطلب الرسمي نستخدم الفعل في البداية ثم Sie:</p><div class="example-grid"><div class="example"><div class="de">Warten Sie bitte!</div><div class="ar">انتظر من فضلك / من فضلكم!</div></div><div class="example"><div class="de">Öffnen Sie das Fenster!</div><div class="ar">افتح النافذة من فضلك!</div></div></div></section><section class="lesson-section"><h3>3. الاقتراحات</h3><p>يمكن اقتراح شيء باستعمال <b>Wollen wir ...?</b> أو <b>Sollen wir ...?</b> أو <b>Wie wäre es mit ...?</b>.</p><div class="example-grid"><div class="example"><div class="de">Wollen wir ins Kino gehen?</div><div class="ar">هل نذهب إلى السينما؟</div></div><div class="example"><div class="de">Sollen wir zusammen lernen?</div><div class="ar">هل ندرس معاً؟</div></div><div class="example"><div class="de">Soll ich dir helfen?</div><div class="ar">هل أساعدك؟</div></div></div></section>`,ex:[{q:'كيف تطلب رسمياً من شخص أن ينتظر؟',o:['Warte!','Warten Sie bitte!','Du wartest!'],a:'Warten Sie bitte!',why:'الأمر الرسمي: الفعل في البداية ثم Sie.'},{q:'أي جملة اقتراح صحيحة؟',o:['Wollen wir lernen?','Wir wollen lernen?','Wollen lernen wir?'],a:'Wollen wir lernen?',why:'Wollen wir ...? صيغة شائعة لاقتراح نشاط.'}]},
{id:'a1-23',title:'الروابط Konnektoren',type:'grammar',group:'بناء الجملة',goal:'ربط جمل قصيرة باستعمال und وaber وoder وdenn.',intro:'الروابط تجعل الكلام أكثر طبيعية وتسمح بجمع فكرتين في جملة واحدة.',html:`<section class="lesson-section"><h3>1. الروابط الأساسية</h3><table class="grammar-table"><tr><th>الرابط</th><th>المعنى</th><th>وظيفته</th></tr><tr><td>und</td><td>و</td><td>إضافة معلومة</td></tr><tr><td>aber</td><td>لكن</td><td>مقابلة أو اختلاف</td></tr><tr><td>oder</td><td>أو</td><td>اختيار بين شيئين</td></tr><tr><td>denn</td><td>لأن</td><td>ذكر السبب</td></tr></table></section><section class="lesson-section"><h3>2. أمثلة</h3><div class="example-grid"><div class="example"><div class="de">Ich lerne Deutsch und ich lese ein Buch.</div><div class="ar">أتعلم الألمانية وأقرأ كتاباً.</div></div><div class="example"><div class="de">Ich bin müde, aber ich arbeite.</div><div class="ar">أنا متعب، لكنني أعمل.</div></div><div class="example"><div class="de">Möchtest du Tee oder Kaffee?</div><div class="ar">هل تريد الشاي أم القهوة؟</div></div><div class="example"><div class="de">Ich bleibe zu Hause, denn ich bin krank.</div><div class="ar">سأبقى في المنزل لأنني مريض.</div></div></div></section><section class="lesson-section"><h3>3. ترتيب الفعل</h3><p>في هذا المستوى، الروابط المذكورة لا تغيّر ترتيب الجملة الأساسية بعدها؛ يبقى الفعل المصرف في الموقع الثاني في كل جزء من الجملة.</p></section>`,ex:[{q:'Ich möchte schlafen, ___ ich bin müde.',o:['aber','denn','oder'],a:'denn',why:'الجملة الثانية تذكر السبب: أريد النوم لأنني متعب.'},{q:'Möchtest du Wasser ___ Saft?',o:['und','oder','denn'],a:'oder',why:'نستخدم oder للاختيار بين الماء والعصير.'}]},
{id:'a1-24',title:'man وetwas وnichts وalle + المستقبل القريب',type:'grammar',group:'بناء الجملة',goal:'التعبير عن العموم والكمية البسيطة والخطط المستقبلية باستعمال المضارع.',intro:'تساعدك هذه الكلمات على الحديث عن الناس بشكل عام، وعن وجود شيء أو عدمه، وعن خطط قريبة.',html:`<section class="lesson-section"><h3>1. الضمير man</h3><p><b>man</b> يعني «المرء» أو «الناس عموماً»، ويأخذ الفعل معه صيغة المفرد الغائب.</p><div class="example"><div class="de">In Deutschland trinkt man viel Kaffee.</div><div class="ar">يشرب الناس كثيراً من القهوة في ألمانيا.</div></div></section><section class="lesson-section"><h3>2. كلمات الكمية العامة</h3><table class="grammar-table"><tr><th>الكلمة</th><th>المعنى</th><th>مثال</th></tr><tr><td>etwas</td><td>شيء ما / بعض</td><td>Ich möchte etwas essen.</td></tr><tr><td>nichts</td><td>لا شيء</td><td>Ich sehe nichts.</td></tr><tr><td>alle</td><td>الجميع / كل</td><td>Alle sind hier.</td></tr></table></section><section class="lesson-section"><h3>3. المضارع للتعبير عن المستقبل</h3><p>يمكن استعمال Präsens للحديث عن خطة مستقبلية إذا كان الوقت واضحاً من السياق، مثل morgen أو nächste Woche.</p><div class="example-grid"><div class="example"><div class="de">Morgen fahre ich nach Berlin.</div><div class="ar">سأسافر إلى برلين غداً.</div></div><div class="example"><div class="de">Nächste Woche beginnt der Kurs.</div><div class="ar">تبدأ الدورة الأسبوع القادم.</div></div></div><p>لا يتغير تصريف الفعل هنا إلى زمن خاص؛ الذي يوضح المستقبل هو ظرف الوقت والسياق.</p></section>`,ex:[{q:'___ spricht man hier Deutsch.',o:['Man','Alle','Nichts'],a:'Man',why:'man فاعل عام بمعنى الناس أو المرء، والفعل يأتي بصيغة المفرد.'},{q:'Ich habe Hunger. Ich möchte ___ essen.',o:['nichts','etwas','alle'],a:'etwas',why:'etwas تعني شيئاً ما، وهي المناسبة في الجملة.'}]}
];
A1_LESSONS.forEach(l=>l.level='A1');
const LESSONS = [...A1_LESSONS, ...ADVANCED_LESSONS];

const EXTRA_KEY='deutsch-coach-v2';
let extra={};try{extra=JSON.parse(localStorage.getItem(EXTRA_KEY))||{}}catch(e){}
extra.lessonProgress=extra.lessonProgress||{};
const progress=extra.lessonProgress;
extra.examResults=extra.examResults||{};
let active=LESSONS[0].id, filter='all', levelFilter='all', query='', examMode=false, currentExam=null;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(EXTRA_KEY,JSON.stringify(extra))}catch(e){}}
function renderProgress(){const n=LESSONS.filter(l=>progress[l.id]).length,p=Math.round(n/LESSONS.length*100);$('#progressText').textContent=p+'%';$('#progressBar').style.width=p+'%';$('#progressCount').textContent=n+' من '+LESSONS.length+' درساً';}
function visibleLessons(){return LESSONS.filter(l=>(levelFilter==='all'||l.level===levelFilter)&&(filter==='all'||l.type===filter)&&(`${l.title} ${l.group} ${l.goal}`).toLowerCase().includes(query.toLowerCase()))}
function renderList(){const items=visibleLessons();$('#lessonCount').textContent=items.length;$('#lessonList').innerHTML=items.length?items.map((l,i)=>`<button class="lesson-link ${l.id===active?'active':''}" data-open="${l.id}"><span class="lesson-num">${String(LESSONS.indexOf(l)+1).padStart(2,'0')}</span><span><strong>${esc(l.title)}</strong><small>${esc(l.group)}</small></span><span class="done-mark">${progress[l.id]?'✓':''}</span></button>`).join(''):'<p class="muted">لا توجد دروس مطابقة للبحث.</p>';}
function renderLesson(){examMode=false;currentExam=null;const l=LESSONS.find(x=>x.id===active)||LESSONS[0],i=LESSONS.indexOf(l),done=!!progress[l.id];$('#lessonPanel').innerHTML=`<header class="lesson-head"><div class="lesson-meta"><span class="tag">${esc(l.level||'A1')} · ${esc(l.group)}</span><span class="tag">${l.type==='grammar'?'قواعد':'تواصل وتطبيق'}</span><span class="tag">الدرس ${i+1} من ${LESSONS.length}</span></div><h2>${esc(l.title)}</h2><p>${esc(l.intro)}</p></header>${l.html}<section class="lesson-section"><h3>اختبر فهمك</h3><p>أجب عن الأسئلة التالية. سيظهر التصحيح مع تفسير مختصر بعد اختيارك.</p>${l.ex.map((q,j)=>`<div class="exercise" data-exercise="${j}"><div class="exercise-title">${j+1}. ${esc(q.q)}</div><div class="exercise-options">${q.o.map(o=>`<button class="answer-option" data-answer="${esc(o)}">${esc(o)}</button>`).join('')}</div><div class="exercise-feedback" id="feedback-${j}"></div></div>`).join('')}</section><div class="lesson-actions"><button class="action-btn primary" id="completeBtn">${done?'✓ تم إكمال الدرس':'أنهيت الدرس ✓'}</button><button class="action-btn" id="prevBtn" ${i===0?'disabled':''}>الدرس السابق</button><button class="action-btn" id="nextBtn" ${i===LESSONS.length-1?'disabled':''}>الدرس التالي ←</button></div>`;renderProgress();renderList();}
function renderExamHome(){examMode=true;currentExam=null;const levels=['A1','A2','B1'];$('#lessonPanel').innerHTML=`<section class="exam-home"><span class="eyebrow">LEVEL CHECK</span><h2>اختبارات المستويات</h2><p class="exam-intro">اختبر فهمك بعد دراسة الدروس. يتكوّن كل اختبار من 10 أسئلة متنوعة من قواعد المستوى وتطبيقاته. اختر إجابة لكل سؤال ثم اضغط على تصحيح الاختبار لترى نتيجتك والإجابات الصحيحة.</p><div class="exam-cards">${levels.map(level=>{const r=extra.examResults[level];return `<article class="exam-card"><h3>اختبار ${level}</h3><p>10 أسئلة · علامة من 10 · النجاح من 7/10</p><p>${r?`أفضل نتيجة: <b>${r.best}/10</b>`:'لم تجتز هذا الاختبار بعد.'}</p><button data-start-exam="${level}">ابدأ اختبار ${level}</button></article>`}).join('')}</div><p class="exam-intro" style="margin-top:20px">نصيحة: حاول حل الاختبار دون الرجوع إلى الشرح، ثم راجع الدروس التي أخطأت فيها.</p></section>`;}
function buildExam(level){const lessons=LESSONS.filter(l=>l.level===level),pool=[];lessons.forEach(l=>l.ex.forEach(q=>pool.push({...q,lessonTitle:l.title,lessonId:l.id})));if(!pool.length)return [];const count=Math.min(10,pool.length),picked=[];for(let i=0;i<count;i++){const idx=Math.floor(i*pool.length/count);picked.push(pool[idx]);}return picked;}
function startExam(level){const questions=buildExam(level);if(!questions.length)return;examMode=true;currentExam={level,questions,answers:{},submitted:false};renderExam();}
function renderExam(){if(!currentExam)return;const ex=currentExam,answered=Object.keys(ex.answers).length;$('#lessonPanel').innerHTML=`<section class="exam-view"><span class="eyebrow">${ex.level} · EXAM</span><h2>اختبار مستوى ${ex.level}</h2><p class="exam-intro">أجب عن الأسئلة العشرة. اختر إجابة واحدة لكل سؤال، ويمكنك تغيير اختيارك قبل التصحيح.</p><div class="progress-head"><span>الإجابات المختارة</span><strong>${answered} من ${ex.questions.length}</strong></div><div class="progress-track"><i style="width:${answered/ex.questions.length*100}%"></i></div>${ex.questions.map((q,i)=>`<article class="exam-question"><h3>${i+1}. ${esc(q.q)}</h3><div class="exam-options">${q.o.map(o=>`<button ${ex.submitted?'disabled':''} class="${ex.answers[i]===o?'selected':''}" data-exam-answer="${i}" data-exam-value="${esc(o)}">${esc(o)}</button>`).join('')}</div>${ex.submitted?`<p class="exercise-feedback show ${ex.answers[i]===q.a?'good':'bad'}">${ex.answers[i]===q.a?'إجابة صحيحة.':'الإجابة الصحيحة: '+esc(q.a)+'.'} ${esc(q.why)}</p>`:''}<small class="muted">من درس: ${esc(q.lessonTitle)}</small></article>`).join('')}${ex.submitted?`<div class="exam-result ${ex.score>=7?'pass':'fail'}"><strong>نتيجتك: ${ex.score} / ${ex.questions.length}</strong><p>${ex.score>=7?'أحسنت! اجتزت الاختبار بنجاح.':'لم تصل إلى علامة النجاح بعد. راجع الدروس وحاول مرة أخرى.'}</p><p>النسبة: ${Math.round(ex.score/ex.questions.length*100)}%</p></div><button class="exam-submit" id="retryExam">إعادة الاختبار</button>`:`<button class="exam-submit" id="submitExam" ${answered!==ex.questions.length?'disabled':''}>تصحيح الاختبار</button><p class="exam-intro">يجب اختيار إجابة لكل سؤال قبل التصحيح.</p>`}<button class="exam-back" id="examBack">العودة إلى اختبارات المستويات</button></section>`;}
function submitExam(){if(!currentExam||currentExam.submitted)return;const ex=currentExam;ex.score=ex.questions.reduce((n,q,i)=>n+(ex.answers[i]===q.a?1:0),0);ex.submitted=true;const old=extra.examResults[ex.level]||{best:0,attempts:0};extra.examResults[ex.level]={best:Math.max(old.best,ex.score),attempts:old.attempts+1,last:ex.score};save();renderExam();}
function openLesson(id){active=id;renderLesson();if(window.innerWidth<700)$('#lessonPanel').scrollIntoView({behavior:'smooth',block:'start'});}
$('#lessonList').addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b)openLesson(b.dataset.open)});
$('#examEntry').addEventListener('click',()=>{renderExamHome();if(window.innerWidth<700)$('#lessonPanel').scrollIntoView({behavior:'smooth',block:'start'});});
$('#search').addEventListener('input',e=>{query=e.target.value;renderList()});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderList()}));
document.querySelectorAll('[data-level]').forEach(b=>b.addEventListener('click',()=>{levelFilter=b.dataset.level;document.querySelectorAll('[data-level]').forEach(x=>x.classList.toggle('active',x===b));const first=visibleLessons()[0];if(first)active=first.id;renderLesson()}));
$('#lessonPanel').addEventListener('click',e=>{
 const start=e.target.closest('[data-start-exam]');if(start){startExam(start.dataset.startExam);return;}
 const examAnswer=e.target.closest('[data-exam-answer]');if(examAnswer&&currentExam&&!currentExam.submitted){currentExam.answers[examAnswer.dataset.examAnswer]=examAnswer.dataset.examValue;renderExam();return;}
 if(e.target.closest('#submitExam')){submitExam();return;}
 if(e.target.closest('#retryExam')){startExam(currentExam.level);return;}
 if(e.target.closest('#examBack')){renderExamHome();return;}
 const say=e.target.closest('[data-say]');if(say){if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(say.dataset.say);u.lang='de-DE';u.rate=.88;speechSynthesis.cancel();speechSynthesis.speak(u)}return;}
 const answer=e.target.closest('[data-answer]');if(answer){const card=answer.closest('.exercise'),idx=+card.dataset.exercise,l=LESSONS.find(x=>x.id===active),q=l.ex[idx],feedback=card.querySelector('.exercise-feedback');if(card.dataset.answered)return;card.dataset.answered='1';card.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(b.dataset.answer===q.a)b.classList.add('correct');else if(b===answer)b.classList.add('wrong')});const good=answer.dataset.answer===q.a;feedback.className='exercise-feedback show '+(good?'good':'bad');feedback.textContent=(good?'إجابة صحيحة! ':'ليست الإجابة الصحيحة. ')+q.why;return;}
 if(e.target.closest('#completeBtn')){progress[active]=!progress[active];save();renderLesson();return;}
 if(e.target.closest('#prevBtn')){const list=visibleLessons(),i=list.findIndex(l=>l.id===active);if(i>0)openLesson(list[i-1].id);return;}
 if(e.target.closest('#nextBtn')){const list=visibleLessons(),i=list.findIndex(l=>l.id===active);if(i>=0&&i<list.length-1)openLesson(list[i+1].id);return;}
});
renderProgress();renderList();renderLesson();
